-- The two accounts, at the ids they have on the live database, and
-- every row stamped with its owner's id the way 0007 stamped them there.
-- Each `slug` holds the key, as a new account's does: nothing reads it.
UPDATE cards SET owner_id = CASE owner WHEN 'matt' THEN 1 WHEN 'kayla' THEN 3 END;
UPDATE decks SET owner_id = CASE owner WHEN 'matt' THEN 1 WHEN 'kayla' THEN 3 END,
                 key = 'd' || printf('%07d', id);

-- Full-text rows, rebuilt from what was inserted above.
SELECT c.id, c.name, c.type_line, c.oracle_text, c.flavor_text,
       (SELECT GROUP_CONCAT(keyword,' ') FROM card_keywords k WHERE k.card_id = c.id),
       (SELECT GROUP_CONCAT(tag,' ') FROM card_tags t WHERE t.card_id = c.id)
FROM cards c;
