INSERT INTO tags (tag,kind,label,description) VALUES ('activate-from-graveyard','oracle','activate from graveyard','Abilities that can be activated from inside a graveyard.');
INSERT INTO tags (tag,kind,label,description) VALUES ('bottomless-mana-sink','oracle','bottomless mana sink','Repeatable effects that, if an arbitrary amount of mana is dumped into them, will probably win you the game—for example, by drawing your whole deck, creating an arbitrarily large attacker, making an endless army of tokens, gaining infinite life, etc.');
INSERT INTO tags (tag,kind,label,description) VALUES ('burn-player','oracle','burn player',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cast-trigger-you','oracle','cast trigger-you','Whenever you cast X, do something.');
INSERT INTO tags (tag,kind,label,description) VALUES ('castable-from-exile','oracle','castable from exile','Cards you can cast or access from exile.');
INSERT INTO tags (tag,kind,label,description) VALUES ('cheaper-than-mv','oracle','cheaper than mv','The actual cost you pay for an effect (or for an alternate mode) will often be lower than the card''s mana value.');
INSERT INTO tags (tag,kind,label,description) VALUES ('commander-identity-matters','oracle','commander identity matters','Cards that care about your commander''s color identity.');
INSERT INTO tags (tag,kind,label,description) VALUES ('counterspell-noncreature','oracle','counterspell-noncreature','Counterspells that call out noncreatures specifically.');
INSERT INTO tags (tag,kind,label,description) VALUES ('counterspell-with-set-mechanic','oracle','counterspell with set mechanic',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('curiosity','oracle','curiosity','Draw cards when dealing damage to an opponent');
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-2xm-r-two-color','oracle','cycle-2xm-r-two-color',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-a25-r-two-color','oracle','cycle-a25-r-two-color',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-ala-esper-capsule','oracle','cycle-ala-esper-capsule',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-c16-undaunted-spell','oracle','cycle-c16-undaunted-spell',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-cmr-will','oracle','cycle-cmr-will',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-dis-u-split','oracle','cycle-dis-u-split',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-m21-garruk-vertical','oracle','cycle-m21-garruk-vertical',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-mkm-r-2c-noncreature','oracle','cycle-mkm-r-2c-noncreature',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-soc-guest-lecturer','oracle','cycle-soc-guest-lecturer',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-soc-two-color-prepare','oracle','cycle-soc-two-color-prepare',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-sos-student','oracle','cycle-sos-student',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-znc-face-commander','oracle','cycle-znc-face-commander',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('cycle-znr-r-mdfc','oracle','cycle-znr-r-mdfc',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('delayed-trigger','oracle','delayed trigger','Create a triggered ability that may trigger later. Similar to a [reflexive trigger](reflexive-trigger).');
INSERT INTO tags (tag,kind,label,description) VALUES ('discard','oracle','discard','Gets cards out of your opponent''s hand and into their graveyard.');
INSERT INTO tags (tag,kind,label,description) VALUES ('discount-self','oracle','discount-self','Cards that have a way to reduce their own cost');
INSERT INTO tags (tag,kind,label,description) VALUES ('donate-rampant-growth','oracle','donate rampant growth','Cards that allow you to ramp another player''s mana by putting a land from their (or your) deck onto the battlefield. Compare [donate mana](donate-mana), which lets you add mana directly to their mana pool.');
INSERT INTO tags (tag,kind,label,description) VALUES ('drain-life','oracle','drain life','Hurt your opponent and gain life to match.');
INSERT INTO tags (tag,kind,label,description) VALUES ('egg','oracle','egg','Artifacts that have to be sacrificed to do something.');
INSERT INTO tags (tag,kind,label,description) VALUES ('enchantmentfall','oracle','enchantmentfall','Cards that care about enchantments entering the batllefield.');
INSERT INTO tags (tag,kind,label,description) VALUES ('evasion','oracle','evasion','Creatures that are harder to block through keywords (flying, menace) or other means.');
INSERT INTO tags (tag,kind,label,description) VALUES ('extra-land','oracle','extra land','Effects that allow you to put additional lands from your hand, top of the library, or graveyard onto the battlefield outside of your normal once-per-turn land play. For effects that let you search your library for cards, refer to [tutor land](/tags/card/tutor-land).');
INSERT INTO tags (tag,kind,label,description) VALUES ('full-refund','oracle','full refund','Cards that give you mana equal to or greater than the amount of mana spent for it, either in the form of a immediately usable mana ability, a ritual effect, or untapped lands ');
INSERT INTO tags (tag,kind,label,description) VALUES ('gives-double-strike','oracle','gives double strike',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('gives-flying','oracle','gives flying',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('gives-indestructible','oracle','gives indestructible',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('gives-tap-ability','oracle','gives tap ability',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('gives-unblockable','oracle','gives unblockable',NULL);
INSERT INTO tags (tag,kind,label,description) VALUES ('group-slug','oracle','group slug','Cards that are able to deal damage or otherwise target multiple players at once.');
INSERT INTO tags (tag,kind,label,description) VALUES ('hate-blocker','oracle','hate-blocker',NULL);
