INSERT INTO rulings (oracle_id,published_at,source,comment) VALUES ('25877c41-39a4-4cc3-ac4b-8f3dd06d579b','2026-03-20','wotc','Players can lose more life than they have. For example, say you''re playing a multiplayer game in which one of your opponents has 3 life and your other opponent has 10 life. If you cast Exsanguinate with X of 4, your opponents will wind up at -1 life and 6 life, respectively. You''ll gain 8 life.');
