INSERT INTO decks (id,slug,name,owner,source_file,recorded_date,status,colors,commander,theme,bracket,is_proxy,card_count,owned_count,source_md) VALUES (4,'halo-proxy-astor-equipment','Halo Proxy Deck ("Master Chief, Spartan Hero") — Custom Boros Equipment/Vehicles','matt','decks/2026-08-05-halo-proxy-astor-equipment.md','2026-08-05','Custom proxy deck, purchased from Etsy seller (Halo full-art reskins of real cards). NOT legal for sanctioned play; requires playgroup/rule-0 approval.','Boros (Red/White)','Astor, Bearer of Blades (proxied as "Master Chief, Spartan Hero")','Equipment + Vehicles — Astor digs for gear, equips for {1}, and lets creatures crew Vehicles cheaply; voltron beats and go-wide Equipment payoffs','3 (verified: 2 Game Changers — Ancient Tomb, Farewell — within the ≤3 limit)',1,100,34,NULL);
INSERT INTO decks (id,slug,name,owner,source_file,recorded_date,status,colors,commander,theme,bracket,is_proxy,card_count,owned_count,source_md) VALUES (20,'lol-proxy-valgavoth-sacrifice','League of Legends Proxy Deck (Valgavoth) — Custom Rakdos Sacrifice/Aristocrats','kayla','kayla-decks/2026-08-11-lol-proxy-valgavoth-sacrifice.md','2026-08-11','Custom proxy deck, purchased from Etsy seller (League of Legends full-art reskins of real cards). NOT legal for sanctioned play; requires playgroup/rule-0 approval.','Rakdos (Black/Red)','Valgavoth, Harrower of Souls','Sacrifice/aristocrats + drain — sacrifice-matters payoffs (Blood Artist, Mayhem Devil, Syr Konrad, Massacre Girl/Wurm), symmetrical damage (Kaervek, Mogis, Kardur, Stormfist Crusader) grinding opponents down alongside your own board','3 (contains Game Changer-tier density — Massacre Girl, Massacre Wurm, Rakdos Lord of Riots, Vial Smasher; verify precise count before table use)',1,86,19,NULL);
INSERT INTO decks (id,slug,name,owner,source_file,recorded_date,status,colors,commander,theme,bracket,is_proxy,card_count,owned_count,source_md) VALUES (1,'chaos-incarnate-precon','Chaos Incarnate — Starter Commander Deck Precon','matt','decks/2026-08-05-chaos-incarnate-precon.md','2026-08-05','Stock precon, unmodified','Rakdos (Black/Red)','Kardur, Doomscourge (single commander — Starter decks have no alt commander)','Goad + chaos — Kardur forces opponents'' creatures to attack each other, drains life when attacking creatures die; symmetrical damage/pain payoffs (Dictate of the Twin Gods, Spiteful Visions, Stormfist Crusader) and big demons finish','1-2 (Starter line is the simplest, most budget precon product)',0,100,100,NULL);
INSERT INTO decks (id,slug,name,owner,source_file,recorded_date,status,colors,commander,theme,bracket,is_proxy,card_count,owned_count,source_md) VALUES (2,'elven-council-precon','Elven Council — LOTR: Tales of Middle-earth Commander Precon','matt','decks/2026-08-05-elven-council-precon.md','2026-08-05 (v2 — corrects v1, which omitted Sol Ring)','Stock precon, unmodified','Simic (Green/Blue)','Galadriel, Elven-Queen (deck supports 5 other viable commanders in the 99: Gandalf Westward Voyager, Círdan, Elrond, Erestor, Radagast)','Elf typal + voting/politics ("will of the council" mechanics), with a big-creature subtheme','1-2 (0 Game Changers, no infinite combos out of the box)',0,100,100,NULL);
